/* A SKILL.md imported `with { type: 'text' }` (Bun's text loader): its contents as a string. */
declare module '*/SKILL.md' {
  const text: string
  export default text
}

/* Kehikot's own changes for agent sessions (`server/agentChanges.ts`), imported `with { type: 'text' }`. */
declare module '*/FOR_AGENTS.md' {
  const text: string
  export default text
}
